// ── Database Connection ───────────────────────────────────────
function getDB(): PDO {
    static $pdo = null;
    if ($pdo === null) {
        $dsn = sprintf('mysql:host=%s;port=%s;dbname=%s;charset=%s', DB_HOST, DB_PORT, DB_NAME, DB_CHARSET);
        $pdo = new PDO($dsn, DB_USER, DB_PASS, [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES   => false,
        ]);
    }
    return $pdo;
}

// ── Encryption Helpers ────────────────────────────────────────
function vault_encrypt(string $plaintext): string {
    $key = hex2bin(VAULT_ENCRYPTION_KEY);
    $iv = random_bytes(12); // GCM uses 12-byte IV
    $tag = '';
    $ciphertext = openssl_encrypt($plaintext, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $iv, $tag, '', 16);
    return base64_encode($iv . $tag . $ciphertext);
}

function vault_decrypt(string $encoded): string {
    $key = hex2bin(VAULT_ENCRYPTION_KEY);
    $data = base64_decode($encoded);
    $iv = substr($data, 0, 12);
    $tag = substr($data, 12, 16);
    $ciphertext = substr($data, 28);
    $plaintext = openssl_decrypt($ciphertext, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $iv, $tag);
    if ($plaintext === false) throw new RuntimeException('Decryption failed');
    return $plaintext;
}

// ── JWT Helpers ───────────────────────────────────────────────
function jwt_encode(array $payload): string {
    $header = base64url_encode(json_encode(['alg' => 'HS256', 'typ' => 'JWT']));
    $payload['iat'] = time();
    $payload['exp'] = time() + (JWT_EXPIRY_HOURS * 3600);
    $pay = base64url_encode(json_encode($payload));
    $sig = base64url_encode(hash_hmac('sha256', "$header.$pay", JWT_SECRET, true));
    return "$header.$pay.$sig";
}

function jwt_decode(string $token): ?array {
    $parts = explode('.', $token);
    if (count($parts) !== 3) return null;
    [$h, $p, $s] = $parts;
    $expected = base64url_encode(hash_hmac('sha256', "$h.$p", JWT_SECRET, true));
    if (!hash_equals($expected, $s)) return null;
    $payload = json_decode(base64url_decode($p), true);
    if (!$payload || ($payload['exp'] ?? 0) < time()) return null;
    return $payload;
}

function base64url_encode(string $data): string {
    return rtrim(strtr(base64_encode($data), '+/', '-_'), '=');
}
function base64url_decode(string $data): string {
    return base64_decode(strtr($data, '-_', '+/') . str_repeat('=', 3 - (3 + strlen($data)) % 4));
}

// ── Audit Logger ──────────────────────────────────────────────
function audit_log(string $action, string $entityType, ?int $entityId = null, string $entityName = '', $oldVal = null, $newVal = null): void {
    $db = getDB();
    $userId = $_SERVER['ITOPS_USER_ID'] ?? null;
    $userName = $_SERVER['ITOPS_USER_NAME'] ?? 'System';
    $ip = $_SERVER['REMOTE_ADDR'] ?? '';
    $stmt = $db->prepare('INSERT INTO itops_audit_log (user_id,user_name,action,entity_type,entity_id,entity_name,old_value,new_value,ip_address) VALUES (?,?,?,?,?,?,?,?,?)');
    $stmt->execute([$userId, $userName, $action, $entityType, $entityId, $entityName, 
        $oldVal ? json_encode($oldVal) : null, $newVal ? json_encode($newVal) : null, $ip]);
}

// ── Password Hashing ──────────────────────────────────────────
function hash_password(string $password): string {
    // Prefer Argon2id, but fall back to bcrypt on PHP builds without argon2
    // support (common on shared cPanel hosting). verify_password() handles
    // either algorithm transparently via password_verify().
    if (defined('PASSWORD_ARGON2ID')) {
        return password_hash($password, PASSWORD_ARGON2ID, ['memory_cost' => 65536, 'time_cost' => 4, 'threads' => 3]);
    }
    return password_hash($password, PASSWORD_DEFAULT); // bcrypt
}

function verify_password(string $password, string $hash): bool {
    return password_verify($password, $hash);
}

// ── Response Helpers ──────────────────────────────────────────
function json_response($data, int $code = 200): void {
    http_response_code($code);
    header('Content-Type: application/json');
    echo json_encode($data);
    exit;
}

function error_response(string $message, int $code = 400): void {
    json_response(['error' => ['code' => $code, 'message' => $message]], $code);
}

// ── CORS Headers ──────────────────────────────────────────────
function cors_headers(): void {
    header('Access-Control-Allow-Origin: ' . CORS_ORIGIN);
    header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS');
    header('Access-Control-Allow-Headers: Content-Type, Authorization, X-CSRF-Token');
    header('Access-Control-Allow-Credentials: true');
    if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') { http_response_code(204); exit; }
}
